        get => CapacityReservation?.CapacityReservationGroup?.Id;
        set
        {
            CapacityReservation ??= new CapacityReservationProfile();
            CapacityReservation.CapacityReservationGroup ??= new SubResource();
            CapacityReservation.CapacityReservationGroup.Id = value;
        }
    }

    /// <summary>Specifies the gallery applications that should be made available to the VM/VMSS</summary>
    [JsonIgnore]
    public IList<VMGalleryApplication>? ApplicationProfileGalleryApplications
    {
        get => ApplicationProfile?.GalleryApplications;
        set
        {
            ApplicationProfile ??= new ApplicationProfile();
            ApplicationProfile.GalleryApplications = value;
        }
    }

    /// <summary>Indicates if zone movement is enabled. By default isEnabled is set to false i.e VM can't be moved from one zone to another.</summary>
    [JsonIgnore]
    public bool? ZoneMovementIsEnabled
    {
        get => ResiliencyProfile?.ZoneMovement?.IsEnabled;
        set
        {
            ResiliencyProfile ??= new ResiliencyProfile();
            ResiliencyProfile.ZoneMovement ??= new ZoneMovement();
            ResiliencyProfile.ZoneMovement.IsEnabled = value;
        }
    }
